export const SETTINGS_KEY='ember-vault-settings-v1';
export const DEFAULT_SETTINGS={language:'ko',volume:.5,largeText:false,colorSafe:false,reduceMotion:false,vibration:true,story:true};
export function validSettings(s){return !!(s&&['ko','en','ja'].includes(s.language)&&typeof s.volume==='number'&&Number.isFinite(s.volume)&&s.volume>=0&&s.volume<=1&&['largeText','colorSafe','reduceMotion','vibration','story'].every(k=>typeof s[k]==='boolean'));}
export function loadSettings(storage){try{const s=JSON.parse(storage.getItem(SETTINGS_KEY));return validSettings(s)?s:{...DEFAULT_SETTINGS};}catch{return {...DEFAULT_SETTINGS};}}
export function saveSettings(storage,s){if(!validSettings(s))return false;try{storage.setItem(SETTINGS_KEY,JSON.stringify(s));return true;}catch{return false;}}
export function applySettings(s){if(typeof document==='undefined')return;for(const [key,cls]of [['largeText','large-text'],['colorSafe','color-safe'],['reduceMotion','user-reduced-motion']])document.body.classList.toggle(cls,s[key]);document.body.dataset.vibration=String(s.vibration);document.documentElement.lang=s.language;window.dispatchEvent(new CustomEvent('ember-settings',{detail:s}));}
export function settingsMarkup(s){return `<div class="settings-grid"><label>언어<select id="prefLanguage"><option value="ko" ${s.language==='ko'?'selected':''}>한국어</option><option value="en" ${s.language==='en'?'selected':''}>English</option><option value="ja" ${s.language==='ja'?'selected':''}>日本語</option></select></label><label>음악·효과음 음량<input id="prefVolume" type="range" min="0" max="1" step="0.05" value="${s.volume}"></label>${[['largeText','큰 글씨'],['colorSafe','색 구분 보조'],['reduceMotion','화면 흔들림·움직임 줄이기'],['vibration','진동 사용'],['story','구역 이야기 자동 재생']].map(([key,label])=>`<label><input type="checkbox" id="pref-${key}" ${s[key]?'checked':''}>${label}</label>`).join('')}</div><div class="modal-actions"><button class="large-button" data-act="applySettings">설정 적용</button></div><h3>원정 기록 파일</h3><p>현재 원정·불씨·최고 기록·설정·상세 연습 저장을 함께 내보냅니다. 가져올 때는 내용을 확인한 뒤 현재 기록을 바꿉니다.</p><div class="modal-actions"><button class="keyword-button" data-act="exportSave">저장 내보내기</button><button class="keyword-button" data-act="importSave">저장 가져오기</button></div><h3>오프라인과 설치</h3><p>첫 온라인 실행 뒤 게임 화면을 오프라인에서도 열 수 있습니다. 전체 음원·그림은 추가 저장할 수 있습니다.</p><div class="modal-actions"><button class="keyword-button" data-act="installApp">홈 화면에 설치</button><button class="keyword-button" data-act="offlinePack">전체 오프라인 저장</button><button class="keyword-button" data-act="applyUpdate">준비된 업데이트 적용</button></div><p id="offlineStatus" role="status"></p><h3>제작과 권리</h3><a href="./credits.html" target="_blank" rel="noopener">음원·그림·외부 코드 출처 보기</a>`;}
